const data = $json;

const errors = [];

if (!data.name || data.name.trim() === '') {
  errors.push('Missing name');
}

if (!data.message || data.message.trim() === '') {
  errors.push('Missing message');
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

let email_valid = true;

if (!data.email || data.email.trim() === '') {
  email_valid = false;
  errors.push('Missing email');
} else if (!emailRegex.test(data.email)) {
  email_valid = false;
  errors.push('Invalid email format');
}

return [
  {
    json: {
      ...data,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      email_valid,
      validation_errors: errors
    }
  }
];

const items = $input.all();

return items.map(item => {
  const text = item.json.output?.[0]?.content?.[0]?.text;

  if (!text) {
    throw new Error('AI output text not found');
  }

  const aiResult = JSON.parse(text);

  const originalData = $('Append row in sheet').first().json;

  return {
    json: {
      ID: originalData.ID,
      NAME: originalData.NAME,
      EMAIL: originalData.EMAIL,
      SUBJECT: originalData.SUBJECT,
      MESSAGE: originalData.MESSAGE,
      RECEIVED_AT: originalData.RECEIVED_AT,

      CATEGORY: aiResult.category,
      PRIORITY: aiResult.priority,
      DEPARTMENT: aiResult.department,
      CAN_AUTO_REPLY: aiResult.can_auto_reply,
      SUMMARY: aiResult.summary,
      SUGGESTED_REPLY: aiResult.suggested_reply,
      CONFIDENCE: aiResult.confidence
    }
  };
});

const data = $json;
const errors = [];

const allowedCategories = [
  'reklamacja',
  'zwrot',
  'dostawa',
  'faktura',
  'marketing',
  'współpraca',
  'zamówienie',
  'pytanie o produkt',
  'inne',
  'spam'
];

const allowedPriorities = [
  'HIGH',
  'MEDIUM',
  'LOW'
];

const allowedDepartments = [
  'reklamacje',
  'zwroty',
  'dostawa',
  'sprzedaż',
  'zamówienia',
  'księgowość',
  'marketing',
  'współpraca',
  'brak'
];

// ==========================================
// MODEL 1 — CATEGORY
// ==========================================

if (
  typeof data.CATEGORY !== 'string' ||
  !allowedCategories.includes(data.CATEGORY)
) {
  errors.push(`Invalid category: ${data.CATEGORY}`);
}

// ==========================================
// MODEL 1 — PRIORITY
// ==========================================

if (
  typeof data.PRIORITY !== 'string' ||
  !allowedPriorities.includes(data.PRIORITY)
) {
  errors.push(`Invalid priority: ${data.PRIORITY}`);
}

// ==========================================
// MODEL 1 — DEPARTMENT
// ==========================================

if (
  typeof data.DEPARTMENT !== 'string' ||
  !allowedDepartments.includes(data.DEPARTMENT)
) {
  errors.push(`Invalid department: ${data.DEPARTMENT}`);
}

// ==========================================
// MODEL 1 — CAN_AUTO_REPLY
// ==========================================

if (typeof data.CAN_AUTO_REPLY !== 'boolean') {
  errors.push('CAN_AUTO_REPLY must be a boolean');
}

// ==========================================
// SUMMARY
// ==========================================

if (
  typeof data.SUMMARY !== 'string' ||
  data.SUMMARY.trim() === ''
) {
  errors.push('Missing SUMMARY');
}

// ==========================================
// SUGGESTED_REPLY
// ==========================================

// Suggested reply jest wymagany dla każdej wiadomości
// poza spamem — również gdy CAN_AUTO_REPLY = false.

if (data.CATEGORY !== 'spam') {
  if (
    typeof data.SUGGESTED_REPLY !== 'string' ||
    data.SUGGESTED_REPLY.trim() === ''
  ) {
    errors.push('Missing SUGGESTED_REPLY');
  }
}

// ==========================================
// CONFIDENCE
// ==========================================

// Confidence jest obecnie wyliczane przez
// Calculate Confidence, a nie przez LLM.

if (
  typeof data.CONFIDENCE !== 'number' ||
  data.CONFIDENCE < 0 ||
  data.CONFIDENCE > 1
) {
  errors.push('CONFIDENCE must be a number between 0 and 1');
}

// ==========================================
// CONSENSUS SCORE
// ==========================================

if (
  typeof data.CONSENSUS_SCORE !== 'number' ||
  data.CONSENSUS_SCORE < 0 ||
  data.CONSENSUS_SCORE > 6
) {
  errors.push('CONSENSUS_SCORE must be a number between 0 and 6');
}

// ==========================================
// MODEL 2 — CATEGORY
// ==========================================

if (
  typeof data.MODEL_2_CATEGORY !== 'string' ||
  !allowedCategories.includes(data.MODEL_2_CATEGORY)
) {
  errors.push(`Invalid Model 2 category: ${data.MODEL_2_CATEGORY}`);
}

// ==========================================
// MODEL 2 — PRIORITY
// ==========================================

if (
  typeof data.MODEL_2_PRIORITY !== 'string' ||
  !allowedPriorities.includes(data.MODEL_2_PRIORITY)
) {
  errors.push(`Invalid Model 2 priority: ${data.MODEL_2_PRIORITY}`);
}

// ==========================================
// MODEL 2 — DEPARTMENT
// ==========================================

if (
  typeof data.MODEL_2_DEPARTMENT !== 'string' ||
  !allowedDepartments.includes(data.MODEL_2_DEPARTMENT)
) {
  errors.push(`Invalid Model 2 department: ${data.MODEL_2_DEPARTMENT}`);
}

// ==========================================
// MODEL 2 — CAN_AUTO_REPLY
// ==========================================

if (typeof data.MODEL_2_CAN_AUTO_REPLY !== 'boolean') {
  errors.push('MODEL_2_CAN_AUTO_REPLY must be a boolean');
}

// ==========================================
// OUTPUT
// ==========================================

return [
  {
    json: {
      ...data,
      ai_validation: errors.length === 0,
      ai_validation_errors: errors
    }
  }
];

