const model1 = $('Parse AI Output').first().json;

const model2Text = $input.first().json.output?.[0]?.content?.[0]?.text;

if (!model2Text) {
  throw new Error('Model 2 output not found');
}

const model2 = JSON.parse(model2Text);

// ==========================================
// PORÓWNANIE MODELI
// ==========================================

let score = 0;

// CATEGORY = 2 punkty
if (model1.CATEGORY === model2.category) {
  score += 2;
}

// PRIORITY = 1 punkt
if (model1.PRIORITY === model2.priority) {
  score += 1;
}

// DEPARTMENT = 1 punkt
if (model1.DEPARTMENT === model2.department) {
  score += 1;
}

// CAN_AUTO_REPLY = 2 punkty
if (model1.CAN_AUTO_REPLY === model2.can_auto_reply) {
  score += 2;
}

// ==========================================
// WYLICZENIE CONFIDENCE
// ==========================================

let confidence;

if (score === 6) {
  confidence = 0.95;
} else if (score === 5) {
  confidence = 0.85;
} else if (score === 4) {
  confidence = 0.70;
} else if (score === 3) {
  confidence = 0.55;
} else {
  confidence = 0.40;
}

// ==========================================
// DODATKOWY GUARDRAIL
// ==========================================

// Jeżeli modele nie zgadzają się co do możliwości
// automatycznej odpowiedzi, confidence nie może być wysokie.

if (model1.CAN_AUTO_REPLY !== model2.can_auto_reply) {
  confidence = Math.min(confidence, 0.70);
}

// ==========================================
// OUTPUT
// ==========================================

return [
  {
    json: {
      ...model1,

      CONFIDENCE: confidence,

      CONSENSUS_SCORE: score,

      MODEL_2_CATEGORY: model2.category,
      MODEL_2_PRIORITY: model2.priority,
      MODEL_2_DEPARTMENT: model2.department,
      MODEL_2_CAN_AUTO_REPLY: model2.can_auto_reply
    }
  }
];

const data = $json.body;

return {
  json: {
    ...data,
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    received_at: new Date().toISOString()
  }
};
